bounded_host_request.command:
set -euo pipefail
root="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
stage="$root/.worktrees/menu-idempotent-8dc8d56-20261115"
container="$(docker ps --format '{{.Names}}' | grep -E '(^|[-_])gaybbs([-_]|$)' | head -n1)"
test -n "$container" || exit 61
project="$(docker inspect -f '{{index .Config.Labels "com.docker.compose.project"}}' "$container")"
query="SELECT state,CASE WHEN message_id IS NULL THEN 'empty' ELSE 'set' END FROM board_menu_panels WHERE chat_id=-1003770334893 AND panel_type='posting' LIMIT 1"
output="$(docker compose -p "$project" --project-directory "$root/deploy" -f "$stage/deploy/gserver-compose.yaml" exec -T postgres psql -U gace -d gaybbs -t -A -c "$query" 2>/dev/null || true)"
case "$output" in
 needs_reconcile\|set*) exit 81;;
 verified\|set*) exit 82;;
 published\|set*) exit 83;;
 publishing\|set*) exit 84;;
 *\|empty*) exit 85;;
 "") exit 86;;
 *) exit 87;;
esac
